import{_ as a,a as r}from"./chunks/6_paint_20200521175459.xRqAujek.js";import{_ as t,o as i,c as l,a0 as o}from"./chunks/framework.DqMqoJl9.js";const g=JSON.parse('{"title":"性能优化的指标和工具","description":"","frontmatter":{},"headers":[],"relativePath":"performance/1-target.md","filePath":"performance/1-target.md","lastUpdated":1791573371000}'),s={name:"performance/1-target.md"};function n(p,e,h,c,d,m){return i(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="性能优化的指标和工具" tabindex="-1">性能优化的指标和工具 <a class="header-anchor" href="#性能优化的指标和工具" aria-label="Permalink to &quot;性能优化的指标和工具&quot;">​</a></h1><h2 id="_1-性能优化的目的" tabindex="-1">1 性能优化的目的 <a class="header-anchor" href="#_1-性能优化的目的" aria-label="Permalink to &quot;1 性能优化的目的&quot;">​</a></h2><h2 id="_2-性能指标和优化指标" tabindex="-1">2 性能指标和优化指标 <a class="header-anchor" href="#_2-性能指标和优化指标" aria-label="Permalink to &quot;2 性能指标和优化指标&quot;">​</a></h2><h2 id="_3-rail-测量模型" tabindex="-1">3 RAIL 测量模型 <a class="header-anchor" href="#_3-rail-测量模型" aria-label="Permalink to &quot;3 RAIL 测量模型&quot;">​</a></h2><h2 id="_4-工具之-webpagetests" tabindex="-1">4 工具之 WebPageTests <a class="header-anchor" href="#_4-工具之-webpagetests" aria-label="Permalink to &quot;4 工具之 WebPageTests&quot;">​</a></h2><h2 id="_5-工具之-lighthouse" tabindex="-1">5 工具之 LightHouse <a class="header-anchor" href="#_5-工具之-lighthouse" aria-label="Permalink to &quot;5 工具之 LightHouse&quot;">​</a></h2><h2 id="_6-performance-工具" tabindex="-1">6 performance 工具 <a class="header-anchor" href="#_6-performance-工具" aria-label="Permalink to &quot;6 performance 工具&quot;">​</a></h2><p>Chrome 的开发者工具各有自己的侧重点，如 Network 工具的瀑布图有着资源拉取顺序的详细信息，它的侧重点在于分析网路链路。而 Performance 工具的侧重点则在于前端渲染过程，它拥有帧率条形图、CPU 使用率面积图、资源瀑布图、主线程火焰图、事件总揽等模块，它们和渲染息息相关，善用它们可以清晰地观察整个渲染阶段</p><p>performance 工具如下图：</p><p><img src="'+a+'" alt=""></p><p>参考下面文章：</p><p><a href="https://juejin.im/post/5b65105f5188251b134e9778" target="_blank" rel="noreferrer">https://juejin.im/post/5b65105f5188251b134e9778</a></p><p><a href="https://developers.google.com/web/tools/chrome-devtools/evaluate-performance" target="_blank" rel="noreferrer">https://developers.google.com/web/tools/chrome-devtools/evaluate-performance</a></p><p>下面搬运一点这篇文章的内容：</p><p>跟页面性能挂勾比较深的几个维度是：网络链路、服务器资源、前端渲染效率、客户端硬件</p><p>这几个维度不是互不相关的，反而是犬牙交错的关系。例如渲染过程中浏览器反应很慢，有可能是脚本写得太烂遭遇性能瓶颈，也有可能是应用开太多或者正在打游戏占用了过多计算机资源</p><p><strong>控制面板选项：</strong></p><ul><li>Network 限制网速</li><li>CPU 限制 CPU 资源</li><li>Disable JavaScript samples 使工具忽略记录 JS 的调用栈</li><li>Enable advanced paint instrumentation 详细记录某些渲染事件的细节</li></ul><p><strong>CPU 面积图：</strong></p><ul><li>蓝色：加载（Loading）事件</li><li>黄色：脚本运算（Scripting）事件</li><li>紫色：渲染（Rendering）事件</li><li>绿色：绘制（Painting）事件</li><li>灰色：其他（Other）</li><li>闲置：浏览器空闲</li></ul><p><strong>Frames：</strong></p><p>帧线程，可以看到每一次渲染的页面，鼠标悬浮绿色块可以看到 fps</p><p><strong>渲染事件：</strong></p><ul><li>Parse HTML 解析 HTML</li><li>Evaluate Script 执行 JavaScript</li><li>Recalculate style 计算样式</li><li>Layout 计算每个节点在屏幕中的精确位置和大小</li><li>Update Layer Tree</li><li>Paint 绘制到图层</li><li>Composite Layers 渲染引擎合成图层最终人眼可见</li></ul><h2 id="_7-rendering-工具" tabindex="-1">7 rendering 工具 <a class="header-anchor" href="#_7-rendering-工具" aria-label="Permalink to &quot;7 rendering 工具&quot;">​</a></h2><p>这个工具可以很直观的观察页面的渲染情况：</p><p><img src="'+r+'" alt=""></p><ul><li>Paint flashing 高亮重绘区域</li><li>Layout Shift Regions 高亮移动的区域</li><li>Layer borders 显示图层组合边界</li><li>FPS meter 显示帧率</li><li>Scrolling performance issues 高亮显示影响滚动的元素</li><li>Highlight ad frames</li><li>Hit-test borders</li></ul><h2 id="_8-性能测量-apis" tabindex="-1">8 性能测量 APIs <a class="header-anchor" href="#_8-性能测量-apis" aria-label="Permalink to &quot;8 性能测量 APIs&quot;">​</a></h2>',29)])])}const f=t(s,[["render",n]]);export{g as __pageData,f as default};
